SELECT name,value,description FROM system.settings WHERE name IN ('use_query_cache','use_query_condition_cache','use_uncompressed_cache','enable_filesystem_cache','use_page_cache_with_distributed_cache','force_read_through_distributed_cache') ORDER BY name LIMIT 20 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames
